-- -----------------------------------
-- Table structure for `live_info_details`
-- -----------------------------------

DROP TABLE IF EXISTS `live_info_details`;
CREATE TABLE `live_info_details` (
  `id` int(6) NOT NULL AUTO_INCREMENT,
  `site_id` varchar(40) CHARACTER SET utf8 DEFAULT NULL,
  `ctable` varchar(40) CHARACTER SET utf8 DEFAULT NULL,
  `status` varchar(10) CHARACTER SET utf8 DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `created_by` varchar(40) CHARACTER SET utf8 DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=6014 DEFAULT CHARSET=latin1;

